import fetch from 'node-fetch';
import PizZip from 'pizzip';
import { GoogleGenerativeAI } from '@google/generative-ai';

export const code = async (inputs) => {
  const { apiKey, prompt, systemPrompt, fileUrl } = inputs;

  const fileResponse = await fetch(fileUrl);
  const fileBuffer = await fileResponse.buffer();
  const zip = new PizZip(fileBuffer);

  // Extract presentation metadata
  let metadata = '';
  try {
    const coreProps = zip.files['docProps/core.xml'].asText();
    const titleMatch = coreProps.match(/<dc:title>([^<]*)<\/dc:title>/);
    const authorMatch = coreProps.match(/<dc:creator>([^<]*)<\/dc:creator>/);

    if (titleMatch) metadata += `Title: ${titleMatch[1]}\n`;
    if (authorMatch) metadata += `Author: ${authorMatch[1]}\n`;
  } catch (e) {
    // Metadata not found
  }

  // Extract slides with more structure
  const slides = [];
  const slideFiles = Object.keys(zip.files)
    .filter(name => name.match(/ppt\/slides\/slide\d+\.xml$/))
    .sort((a, b) => parseInt(a.match(/\d+/)[0]) - parseInt(b.match(/\d+/)[0]));

  for (let i = 0; i < slideFiles.length; i++) {
    const slideContent = zip.files[slideFiles[i]].asText();

    // Extract text elements
    const textElements = slideContent.match(/<a:t>([^<]*)<\/a:t>/g) || [];
    const texts = textElements.map(t => t.replace(/<\/?a:t>/g, '')).filter(t => t.trim());

    // Try to identify title (usually first/largest text)
    const title = texts[0] || `Slide ${i + 1}`;
    const content = texts.slice(1).join('\n');

    slides.push({
      number: i + 1,
      title: title,
      content: content
    });
  }

  // Format extracted text
  const extractedText = `
PRESENTATION ANALYSIS

${metadata}

SLIDES:

${slides.map(slide => `
Slide ${slide.number}: ${slide.title}
${slide.content ? slide.content : '(No additional content)'}
---
`).join('\n')}
`.trim();

  // Initialize Gemini
  const genAI = new GoogleGenerativeAI(apiKey);
  const model = genAI.getGenerativeModel({ 
    model: "gemini-2.5-flash",
    systemInstruction: prompt || "You are a helpful assistant analyzing presentation content."
  });

  // Generate content with system prompt and extracted text
  const result = await model.generateContent(prompt);
  const response = await result.response;

  return response.text();
};

import { GoogleGenerativeAI } from '@google/generative-ai';

export const code = async (inputs) => {
  const { apiKey, prompt, fileUrl, mimeType } = inputs;

  // Initialize Gemini
  const genAI = new GoogleGenerativeAI(apiKey);
  const model = genAI.getGenerativeModel({ model: "gemini-2.5-flash" });

  // Fetch the file from URL
  const fileResponse = await fetch(fileUrl);
  const fileBuffer = await fileResponse.arrayBuffer();
  const fileData = Buffer.from(fileBuffer).toString('base64');

  // Generate content with the file
  const result = await model.generateContent([
    {
      inlineData: {
        mimeType: mimeType || 'application/pdf',
        data: fileData
      }
    },
    prompt || "Describe this file"
  ]);

  const response = await result.response;
  return response.text();
};
